下面是人为安排的教学记录，不是实际随机采集的玩家数据。easy/hard 各八条；每行的概率来自设定的旧抽样规则，次数恰好符合比例，但现实中不能用频数反推每次概率。

| 情境 | 实际提示 | 条数 | 成功条数 | 当时选择该提示的概率 |
| --- | --- | --- | --- | --- |
| easy | 文字 | 6 | 6 | 0.75 |
| easy | 地图 | 2 | 2 | 0.25 |
| hard | 文字 | 2 | 0 | 0.25 |
| hard | 地图 | 6 | 2 | 0.75 |

保存为 hint-ope.mjs，运行 node hint-ope.mjs，无额外依赖。naive 是只取匹配记录的成功均值，ips 是上述加权估计；ess=(Σw)²/Σw² 只是权重集中程度的诊断量，不是置信区间或独立玩家数。代码按输入记录检查支持条件，无法替你证明未出现的人群也被覆盖。

```js
/**
 * @file Audit deterministic hint policies using synthetic bandit logs.
 * @author liliwei
 * @date 2026-11-17
 * @LastEditors liliwei
 * @LastEditTime 2026-11-17
 */
import assert from 'node:assert/strict';

/**
 * Evaluate a fixed policy on complete, deduplicated decision records.
 * @param {object[]} rows Records: id, context, action (0/1), prob, reward (0/1).
 * @param {object} policy Action IDs indexed by easy/hard context.
 * @returns {object} IPS estimate and overlap/weight diagnostics, not a confidence interval.
 */
export function evaluate(rows, policy) {
  assert(Array.isArray(rows) && rows.length > 0);
  for (const c of ['easy', 'hard']) assert([0, 1].includes(policy?.[c]));
  const ids = new Set();
  let matched = 0, wins = 0, weighted = 0, sumW = 0, sumW2 = 0, maxW = 0;
  for (const r of rows) {
    assert(r && typeof r.id === 'string' && r.id.length > 0 && !ids.has(r.id));
    ids.add(r.id);
    assert(['easy', 'hard'].includes(r.context) && [0, 1].includes(r.action));
    assert([0, 1].includes(r.reward));
    assert(Array.isArray(r.prob) && r.prob.length === 2);
    for (const p of r.prob) assert(Number.isFinite(p) && p >= 0 && p <= 1);
    assert(Math.abs(r.prob[0] + r.prob[1] - 1) < 1e-12);
    const target = policy[r.context];
    assert(r.prob[r.action] > 0, 'Impossible logged action');
    assert(r.prob[target] > 0, 'Unsupported candidate action');
    const hit = r.action === target;
    const w = hit ? 1 / r.prob[r.action] : 0;
    matched += Number(hit); wins += Number(hit) * r.reward;
    weighted += w * r.reward; sumW += w; sumW2 += w * w;
    maxW = Math.max(maxW, w);
  }
  assert([weighted, sumW, sumW2, sumW * sumW].every(Number.isFinite));
  return { n: rows.length, matched,
    naive: matched ? wins / matched : null,
    ips: weighted / rows.length, maxW,
    ess: sumW2 ? sumW * sumW / sumW2 : 0 };
}

// Hand-built illustration, not an actual randomized experiment or model output.
export const rows = [];
for (const [context, action, count, successes] of [
  ['easy', 0, 6, 6], ['easy', 1, 2, 2],
  ['hard', 0, 2, 0], ['hard', 1, 6, 2],
]) {
  for (let i = 0; i < count; i++) rows.push({
    id: `d${rows.length}`, context, action,
    prob: context === 'easy' ? [0.75, 0.25] : [0.25, 0.75],
    reward: Number(i < successes),
  });
}
export const policies = {
  text: { easy: 0, hard: 0 }, map: { easy: 1, hard: 1 },
  contextual: { easy: 0, hard: 1 },
};
for (const [name, policy] of Object.entries(policies)) {
  console.log(name, JSON.stringify(evaluate(rows, policy)));
}
```
